def {{fn_prefix}}_serialize(root):
    out = []
    def dfs(n):
        if not n: out.append('#'); return
        out.append(str(n.val))
        dfs(n.left); dfs(n.right)
    dfs(root)
    return ','.join(out)

def {{fn_prefix}}_deserialize(data, Node):
    it = iter(data.split(','))
    def build():
        v = next(it)
        if v == '#': return None
        n = Node(int(v))
        n.left = build()
        n.right = build()
        return n
    return build()
